# Generated by Claude (Claude Code).
"""Train PeakCNN on the UHD 620 via DirectML, with freshly generated functions every epoch."""

import copy
import csv
import json
import time
from contextlib import ExitStack
from datetime import datetime
from pathlib import Path

import numpy as np
import torch
import torch.nn.functional as F
import torch_directml

from adversary import VARIANTS, AdversarialTuples
import data
from data import generate_batch
from losses import focal_loss
from model import NUM_SAMPLES, PeakCNN
from optim import Adam, ScheduleFreeAdamW
from plot import plot_training_log, plot_tuples
from sampler import LossGuidedSampler

EPOCHS = 50
FUNCTIONS_PER_EPOCH = 12_800
BATCH_SIZE = 64
LEARNING_RATE = 1e-3
# "adam" (optim.Adam, runs fully on DirectML), "adam_amsgrad" (the same with AMSGrad),
# "schedule_free_adamw" (optim.ScheduleFreeAdamW) or "sgd" (torch.optim.SGD).
OPTIMIZER = "adam"
SGD_MOMENTUM = 0.9      # only used when OPTIMIZER = "sgd"
SF_WARMUP_FRACTION = 0.05  # schedule_free_adamw: linear warmup over this share of all steps
SEED = 0
CHANNELS = 32           # conv channels per layer of PeakCNN
LOSS = "cross_entropy"  # training objective: "cross_entropy" or "focal"
FOCAL_GAMMA = 2.0       # focusing parameter, only used when LOSS = "focal"
# Online hard example mining: if set, each step generates OHEM_POOL candidates, scores them
# without gradients and trains on the BATCH_SIZE candidates with the highest loss. None = off.
OHEM_POOL = None
# How training functions are drawn: "uniform" (data.generate_batch), "loss_guided"
# (sampler.py: per-class loss predictors pick high-loss parameters from a candidate pool) or
# "adversarial" (adversary.py: ADVERSARY_COPIES tuples per pattern form the batch, each tuple
# ascending its loss with Adam; needs BATCH_SIZE = 10 * ADVERSARY_COPIES).
SAMPLER = "uniform"
POOL_FACTOR = 8          # loss_guided: candidates per batch slot
PREDICTOR_LR = 1e-3      # loss_guided: Adam learning rate of the loss predictors
ADVERSARY_LR = 1e-2      # adversarial: Adam learning rate of the tuples' gradient ascent
ADVERSARY_COPIES = 1     # adversarial: tuples per extrema pattern (10 patterns)
EVAL_FUNCTIONS = 12_800  # loss_guided, adversarial: uniform functions scored after each epoch
# If set, the same FIXED_EVAL_FUNCTIONS uniform functions (drawn once with FIXED_EVAL_SEED, separate
# from the training data and the usual seed-12345 test set) are scored after every epoch, so their
# curves contain no sampling noise between epochs. For schedule_free_adamw, x, y and z are scored
# separately. Adds columns to log.csv; the time it takes is not counted in "seconds". None = off.
FIXED_EVAL_FUNCTIONS = None
FIXED_EVAL_SEED = 2026
PROJECT_DIR = Path(__file__).resolve().parent
# Each run gets runs/<date>_<time>/ with config.json, model.pt, log.csv and chart.png.
RUNS_DIR = PROJECT_DIR / "runs"
# "loss" is always the cross-entropy (comparable across runs); "objective" is the value optimized.
# With OHEM, "loss" and "accuracy" are measured over all candidates, "objective" over the trained
# (selected) functions, and "functions_seen" counts trained functions. With the loss-guided
# sampler, "loss" and "accuracy" come from EVAL_FUNCTIONS fresh uniform functions scored after
# each epoch, and "predictor_corr" is the correlation between predicted and actual log-loss there.
# With the adversarial tuples, "loss" and "accuracy" also come from EVAL_FUNCTIONS fresh uniform
# functions, and "objective" is the mean loss on the ten tuples during the epoch; the run folder
# additionally gets tuples.csv (the tuples after every epoch) and tuples.png (the final tuples).
LOG_COLUMNS = ["epoch", "loss", "objective", "accuracy", "seconds", "functions_seen", "timestamp",
               "predictor_corr"]


def main() -> None:
    if LOSS not in ("cross_entropy", "focal"):
        raise ValueError(f"unknown LOSS {LOSS!r}; use 'cross_entropy' or 'focal'")
    if OPTIMIZER not in ("adam", "adam_amsgrad", "schedule_free_adamw", "sgd"):
        raise ValueError(f"unknown OPTIMIZER {OPTIMIZER!r}; use 'adam', 'adam_amsgrad', "
                         "'schedule_free_adamw' or 'sgd'")
    if OHEM_POOL is not None and OHEM_POOL <= BATCH_SIZE:
        raise ValueError(f"OHEM_POOL ({OHEM_POOL}) must be larger than BATCH_SIZE ({BATCH_SIZE})")
    if SAMPLER not in ("uniform", "loss_guided", "adversarial"):
        raise ValueError(f"unknown SAMPLER {SAMPLER!r}; use 'uniform', 'loss_guided' or 'adversarial'")
    guided = SAMPLER == "loss_guided"
    adversarial = SAMPLER == "adversarial"
    if (guided or adversarial) and OHEM_POOL is not None:
        raise ValueError(f"OHEM and the {SAMPLER} sampler can't be combined")
    if adversarial and BATCH_SIZE != len(VARIANTS) * ADVERSARY_COPIES:
        raise ValueError(f"the adversarial sampler trains on its {len(VARIANTS) * ADVERSARY_COPIES} "
                         f"tuples; set BATCH_SIZE = {len(VARIANTS) * ADVERSARY_COPIES}")
    torch.manual_seed(SEED)
    rng = np.random.default_rng(SEED)
    device = torch_directml.device()

    model = PeakCNN(NUM_SAMPLES, CHANNELS).to(device)
    steps_per_epoch = FUNCTIONS_PER_EPOCH // BATCH_SIZE
    schedule_free = OPTIMIZER == "schedule_free_adamw"
    sf_warmup_steps = round(SF_WARMUP_FRACTION * EPOCHS * steps_per_epoch) if schedule_free else None
    if OPTIMIZER in ("adam", "adam_amsgrad"):
        optimizer = Adam(model.parameters(), lr=LEARNING_RATE, amsgrad=OPTIMIZER == "adam_amsgrad")
    elif schedule_free:
        optimizer = ScheduleFreeAdamW(model.parameters(), lr=LEARNING_RATE, warmup_steps=sf_warmup_steps)
    else:
        optimizer = torch.optim.SGD(model.parameters(), lr=LEARNING_RATE, momentum=SGD_MOMENTUM)
    if guided:
        sampler = LossGuidedSampler(NUM_SAMPLES, device, rng, POOL_FACTOR, PREDICTOR_LR)
        eval_sampler = LossGuidedSampler(NUM_SAMPLES, device, np.random.default_rng(SEED + 1),
                                         POOL_FACTOR, PREDICTOR_LR)  # only its sample_uniform is used
    if adversarial:
        tuples = AdversarialTuples(NUM_SAMPLES, device, rng, ADVERSARY_LR, ADVERSARY_COPIES)
        eval_rng = np.random.default_rng(SEED + 1)

    fixed_versions = []  # weight versions scored on the fixed set ("" = the model's own weights)
    if FIXED_EVAL_FUNCTIONS is not None:
        fixed_f, fixed_y = generate_batch(FIXED_EVAL_FUNCTIONS, NUM_SAMPLES,
                                          np.random.default_rng(FIXED_EVAL_SEED))
        fixed_set = (torch.from_numpy(fixed_f), torch.from_numpy(fixed_y))
        fixed_versions = ["x", "y", "z"] if schedule_free else [""]
        fixed_model = copy.deepcopy(model)  # holds the weights being scored (no RNG use)
    fixed_columns = [f"fixed_{m}{'_' + v if v else ''}" for v in fixed_versions for m in ("loss", "accuracy")]

    run_dir = RUNS_DIR / f"{datetime.now():%Y-%m-%d_%H-%M-%S}"
    run_dir.mkdir(parents=True)
    model_path = run_dir / "model.pt"
    log_path = run_dir / "log.csv"
    chart_path = run_dir / "chart.png"
    functions_seen = 0

    config = {
        "epochs": EPOCHS,
        "functions_per_epoch": FUNCTIONS_PER_EPOCH,
        "batch_size": BATCH_SIZE,
        "learning_rate": LEARNING_RATE,
        "optimizer": OPTIMIZER,
        "momentum": SGD_MOMENTUM if OPTIMIZER == "sgd" else None,
        "sf_warmup_steps": sf_warmup_steps,
        "seed": SEED,
        "warp": data.WARP,
        "num_samples": NUM_SAMPLES,
        "channels": CHANNELS,
        "loss": LOSS,
        "focal_gamma": FOCAL_GAMMA if LOSS == "focal" else None,
        "ohem_pool": OHEM_POOL,
        "sampler": SAMPLER,
        "pool_factor": POOL_FACTOR if guided else None,
        "predictor_lr": PREDICTOR_LR if guided else None,
        "adversary_lr": ADVERSARY_LR if adversarial else None,
        "adversary_copies": ADVERSARY_COPIES if adversarial else None,
        "eval_functions": EVAL_FUNCTIONS if guided or adversarial else None,
        "fixed_eval_functions": FIXED_EVAL_FUNCTIONS,
        "fixed_eval_seed": FIXED_EVAL_SEED if FIXED_EVAL_FUNCTIONS is not None else None,
    }
    (run_dir / "config.json").write_text(json.dumps(config, indent=2) + "\n")

    with open(log_path, "w", newline="") as log_file, ExitStack() as files:
        log = csv.writer(log_file)
        log.writerow(LOG_COLUMNS + fixed_columns)
        if adversarial:
            tuples_file = files.enter_context(open(run_dir / "tuples.csv", "w", newline=""))
            tuples_log = csv.writer(tuples_file)
            tuples_log.writerow(TUPLE_COLUMNS)
            write_tuples(tuples_log, 0, model, tuples)
            tuples_file.flush()

        for epoch in range(1, EPOCHS + 1):
            model.train()
            start = time.perf_counter()
            total_loss = 0.0       # cross-entropy summed over all scored functions
            total_objective = 0.0  # objective summed over the trained functions
            total_correct = 0
            total_seen = 0         # scored functions (= trained functions without OHEM)
            total_trained = 0

            for _ in range(steps_per_epoch):
                if adversarial:
                    x, y, labels = tuples.functions(), tuples.labels_device, tuples.labels
                else:
                    if guided:
                        functions, labels, sampler_inputs = sampler.sample_batch(BATCH_SIZE)
                    else:
                        functions, labels = generate_batch(OHEM_POOL or BATCH_SIZE, NUM_SAMPLES, rng)
                    x = torch.from_numpy(functions).to(device)
                    y = torch.from_numpy(labels).to(device)

                if OHEM_POOL is not None:
                    # Score all candidates without gradients, keep the BATCH_SIZE hardest.
                    with torch.no_grad():
                        pool_logits = model(x)
                        pool_losses = F.cross_entropy(pool_logits, y, reduction="none")
                        pool_correct = (pool_logits.argmax(dim=1) == y).sum()
                    hardest = torch.topk(pool_losses, BATCH_SIZE).indices
                    x_train, y_train = x[hardest], y[hardest]
                else:
                    x_train, y_train = x, y

                logits = model(x_train)
                if guided:
                    per_function = F.cross_entropy(logits, y_train, reduction="none")
                    cross_entropy = per_function.mean()
                else:
                    cross_entropy = F.cross_entropy(logits, y_train)
                if LOSS == "cross_entropy":
                    objective = cross_entropy
                else:
                    objective = focal_loss(logits, y_train, FOCAL_GAMMA)

                optimizer.zero_grad()
                if adversarial:
                    tuples.zero_grad()
                objective.backward()  # adversarial: also the tuples' gradients, at the same state
                optimizer.step()
                if adversarial:
                    tuples.ascent_step()  # Adam step on the tuples that increases the objective
                if guided:  # predictor targets: the losses from before this CNN update
                    sampler.update(per_function, sampler_inputs)

                if OHEM_POOL is not None:
                    ce_value, objective_value = torch.stack(
                        [pool_losses.mean(), objective.detach()]).cpu().tolist()
                    total_correct += pool_correct.item()
                else:
                    ce_value, objective_value = torch.stack(
                        [cross_entropy, objective]).detach().cpu().tolist()
                    total_correct += (logits.argmax(dim=1) == y_train).sum().item()
                total_loss += ce_value * len(labels)
                total_objective += objective_value * len(y_train)
                total_seen += len(labels)
                total_trained += len(y_train)

            mean_loss = total_loss / total_seen
            mean_objective = total_objective / total_trained
            accuracy = total_correct / total_seen
            predictor_corr = ""
            if schedule_free:
                optimizer.eval()  # evaluate and save the averaged weights x, not the gradient point y
            if guided:
                # The sampled batches are deliberately hard, so log fresh uniform functions instead.
                mean_loss, accuracy, predictor_corr = evaluate_uniform(model, sampler, eval_sampler, device)
                predictor_corr = f"{predictor_corr:.4f}"
            if adversarial:
                mean_loss, accuracy = evaluate_fresh(model, eval_rng, device)
                write_tuples(tuples_log, epoch, model, tuples)
                tuples_file.flush()

            state = {k: v.detach().cpu() for k, v in model.state_dict().items()}
            torch.save(state, model_path)
            if schedule_free:
                optimizer.train()

            seconds = time.perf_counter() - start
            functions_seen += total_trained

            fixed_values = []
            for version in fixed_versions:  # after "seconds": not counted as training time
                with torch.no_grad():
                    for p_fixed, p in zip(fixed_model.parameters(), model.parameters()):
                        p_fixed.copy_(optimizer.state[p][version] if version else p)
                fixed_loss, fixed_accuracy = evaluate_set(fixed_model, *fixed_set, device)
                fixed_values += [f"{fixed_loss:.6f}", f"{fixed_accuracy:.6f}"]

            log.writerow([
                epoch,
                f"{mean_loss:.6f}",
                f"{mean_objective:.6f}",
                f"{accuracy:.6f}",
                f"{seconds:.3f}",
                functions_seen,
                datetime.now().isoformat(timespec="seconds"),
                predictor_corr,
            ] + fixed_values)
            log_file.flush()

            print(
                f"epoch {epoch:3d}/{EPOCHS}  "
                f"loss {mean_loss:.4f}  "
                f"acc {accuracy:.2%}  "
                f"({seconds:.1f} s)"
            )

    plot_training_log(log_path, chart_path)
    if adversarial:
        final_losses = tuple_losses(model, tuples)
        plot_tuples(tuples.params(), final_losses, NUM_SAMPLES, run_dir / "tuples.png",
                    f"Adversarial tuples after epoch {EPOCHS}",
                    cols=5 if ADVERSARY_COPIES == 1 else len(VARIANTS))
    print(f"saved weights, training log and chart to {run_dir}")


# tuples.csv: one row per tuple and epoch (epoch 0 = the initial tuples); "variant" is the tuple's
# position in the batch (copy by copy, 10 patterns each); knot positions and
# values are space-separated, edges included; "pre" and "post" are the warp parameters (c, or
# alpha and beta); "loss" is the tuple's cross-entropy at that point.
TUPLE_COLUMNS = ["epoch", "variant", "pattern", "label", "loss", "knot_x", "knot_y", "pre", "post"]


def tuple_losses(model, tuples) -> list[float]:
    """Current per-tuple cross-entropy (no gradients)."""
    with torch.no_grad():
        return F.cross_entropy(model(tuples.functions()), tuples.labels_device, reduction="none").cpu().tolist()


def write_tuples(writer, epoch: int, model, tuples) -> None:
    for k, (p, label, loss) in enumerate(zip(tuples.params(), tuples.labels, tuple_losses(model, tuples))):
        writer.writerow([epoch, k, p.pattern, int(label), f"{loss:.6g}",
                         " ".join(f"{v:.9g}" for v in p.knot_x), " ".join(f"{v:.9g}" for v in p.knot_y),
                         " ".join(f"{v:.9g}" for v in p.pre), " ".join(f"{v:.9g}" for v in p.post)])


def evaluate_set(model, functions: torch.Tensor, labels: torch.Tensor, device, chunk: int = 1024):
    """Mean cross-entropy and accuracy on a given set (CPU tensors), moved to the device in chunks.
    Each chunk's result is read back at once: queuing all chunks without a sync can make
    DirectML run out of memory."""
    total_loss, total_correct = 0.0, 0
    with torch.no_grad():
        for start in range(0, len(labels), chunk):
            x = functions[start:start + chunk].to(device)
            y = labels[start:start + chunk].to(device)
            logits = model(x)
            stats = torch.stack([F.cross_entropy(logits, y, reduction="sum"),
                                 (logits.argmax(dim=1) == y).sum().float()]).cpu().tolist()
            total_loss += stats[0]
            total_correct += int(stats[1])
    return total_loss / len(labels), total_correct / len(labels)


def evaluate_fresh(model, rng, device, chunk: int = 1024):
    """Mean cross-entropy and accuracy on EVAL_FUNCTIONS fresh uniform functions from rng."""
    total_loss, total_correct = 0.0, 0
    with torch.no_grad():
        for start in range(0, EVAL_FUNCTIONS, chunk):
            functions, labels = generate_batch(min(chunk, EVAL_FUNCTIONS - start), NUM_SAMPLES, rng)
            x = torch.from_numpy(functions).to(device)
            y = torch.from_numpy(labels).to(device)
            logits = model(x)
            stats = torch.stack([F.cross_entropy(logits, y, reduction="sum"),
                                 (logits.argmax(dim=1) == y).sum().float()]).cpu().tolist()
            total_loss += stats[0]
            total_correct += int(stats[1])
    return total_loss / EVAL_FUNCTIONS, total_correct / EVAL_FUNCTIONS


def evaluate_uniform(model, sampler, eval_sampler, device, chunk: int = 1024):
    """Mean cross-entropy and accuracy of the model on EVAL_FUNCTIONS fresh uniform functions,
    and the correlation between the sampler's predicted and the actual log-loss on them."""
    total_loss, total_correct, predicted, actual = 0.0, 0, [], []
    with torch.no_grad():
        for start in range(0, EVAL_FUNCTIONS, chunk):
            n = min(chunk, EVAL_FUNCTIONS - start)
            functions, labels, inputs = eval_sampler.sample_uniform(n)
            x = torch.from_numpy(functions).to(device)
            y = torch.from_numpy(labels).to(device)
            logits = model(x)
            losses = F.cross_entropy(logits, y, reduction="none")
            stats = torch.stack([losses.sum(), (logits.argmax(dim=1) == y).sum().float()]).cpu().tolist()
            total_loss += stats[0]
            total_correct += int(stats[1])
            predicted.append(sampler.predict(inputs, n).cpu())
            actual.append(torch.log(losses.clamp_min(1e-6)).cpu())
    corr = float(np.corrcoef(torch.cat(predicted).numpy(), torch.cat(actual).numpy())[0, 1])
    return total_loss / EVAL_FUNCTIONS, total_correct / EVAL_FUNCTIONS, corr


if __name__ == "__main__":
    main()
